import { Canvas, useFrame, useLoader } from '@react-three/fiber';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

function Actor() {
  const model = useLoader(GLTFLoader, '/assets/direct.glb');
  useFrame((_state, _delta) => { /* runtime callback is not resolved by the scanner */ });
  return <mesh name="actor" onClick={selectActor}><primitive object={model.scene} /></mesh>;
}

export function World() {
  return <Canvas><Actor /></Canvas>;
}
